import{_ as i,a0 as d,w as n,s,ao as p,I as l,x as o,a1 as a,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const F=JSON.parse('{"title":"Fedora 上的桌面环境内存占用测试 | LCTT x X-CMD","titleTemplate":false,"description":"Fedora 上的桌面环境内存占用测试 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Fedora 上的桌面环境内存占用测试 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Fedora 上的桌面环境内存占用测试 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191204 Fedora Desktops - Memory Footprints","title":"Fedora 上的桌面环境内存占用测试","tag":"201912","desc":""},"relativePath":"201912/20191204 Fedora Desktops - Memory Footprints.md","filePath":"[post].md"}'),m={name:"201912/20191204 Fedora Desktops - Memory Footprints.md"};function u(f,e,g,h,x,T){const t=d("Link");return n(),s("div",null,[e[15]||(e[15]=p('<h1 id="fedora-上的桌面环境内存占用测试" tabindex="-1">Fedora 上的桌面环境内存占用测试 <a class="header-anchor" href="#fedora-上的桌面环境内存占用测试" aria-label="Permalink to “Fedora 上的桌面环境内存占用测试”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/11/desktop-memory-footprint-816x346.jpg" alt=""></p><p>Fedora 中有 40 多种桌面环境（DE）。每种桌面环境都有自己的优点和缺点。通常，根据功能、外观和其它品质，选择桌面是一件非常个人的偏好。但有时，你选择的桌面环境还会受到硬件限制。</p><p>本文旨在帮助人们根据桌面环境占用的基准内存来比较 Fedora 桌面环境。为了缩小范围，我们仅查看具有正式 Fedora Live 镜像的桌面环境。</p><h3 id="安装与系统配置" tabindex="-1">安装与系统配置 <a class="header-anchor" href="#安装与系统配置" aria-label="Permalink to “安装与系统配置”">​</a></h3><p>每个桌面环境都安装在自己的 KVM 虚拟机上。每个虚拟机都有 1 个 CPU、4GB 内存、15GB virtio 固态磁盘，以及 RHEL 8.0 kvm 上所有其他标准配置。</p><p>用于安装的镜像是标准的 Fedora 31 Live 镜像。对于 GNOME，该镜像是 “Fedora 工作站”。对于其它桌面，使用了相应的 Spin 版本。未对“<ruby>糖葫芦<rt>Sugar On A Stick</rt></ruby>”（SOAS）进行测试，因为它不容易安装到本地驱动器上。</p><p>用 Live CD 启动虚拟机，然后选择“安装到硬盘”。在安装过程中，仅使用默认值。创建了一个 root 用户和一个普通用户。安装并重新启动后，live 镜像已确认不在虚拟 CDROM 中。</p><p>每个桌面环境的设置都没有改动。它们每个都以 Live CD 环境中默认的设置运行。每个桌面环境都是通过普通用户登录的。打开了一个终端，在每台虚拟机中都使用 <code>sudo</code> 运行了 <code>dnf -y update</code>。在更新后，在该 sudo 终端中，每台虚拟机都运行 <code>/sbin/shutdown -h now</code> 以关闭。</p><h3 id="测试方式" tabindex="-1">测试方式 <a class="header-anchor" href="#测试方式" aria-label="Permalink to “测试方式”">​</a></h3><p>每台机器都已启动。桌面环境已通过普通用户登录。打开了三个桌面终端。xterm 从未使用过，始终用的是该桌面环境的终端，例如 konsole。</p><p>在一个终端中，启动 <code>top</code> 并按下 <code>M</code>，以显示按内存排序的进程。在另一个终端中，一个简单的 <code>while</code> 循环每 30 秒显示一次 <code>free -m</code>。第三个终端闲置。</p><p>然后，我等待了 5 分钟。这样就可以让所有启动的服务都启动完成。我记录了最终的 <code>free</code> 结果，以及 <code>top</code> 中最终的前三名内存使用者。</p><h3 id="结果" tabindex="-1">结果 <a class="header-anchor" href="#结果" aria-label="Permalink to “结果”">​</a></h3><ul><li>Cinnamon <ul><li>使用了624 MB</li><li>cinnamon 4.8% / Xorg 2.2% / dnfdragora 1.8%</li></ul></li><li>GNOME <ul><li>使用了 612 MB</li><li>gnome-shell 6.9% / gnome-software 1.8% / ibus-x11 1.5%</li></ul></li><li>KDE <ul><li>使用了 733 MB</li><li>plasmashell 6.2% / kwin_x11 3.6% / akonadi_mailfil 2.9%</li></ul></li><li>LXDE <ul><li>使用了 318 MB</li><li>Xorg 1.9% / nm-applet 1.8% / dnfdragora 1.8%</li></ul></li><li>LXQt <ul><li>使用了 391 MB</li><li>lxqt-panel 2.2% / pcmanfm-qt 2.1% / Xorg 2.1%</li></ul></li><li>MATE <ul><li>使用了 465 MB</li><li>Xorg 2.5% / dnfdragora 1.8% / caja 1.5%</li></ul></li><li>XFCE <ul><li>使用了 448 MB</li><li>Xorg 2.3% / xfwm4 2.0% / dnfdragora 1.8%</li></ul></li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>我会让数字说明一切。</p><p>请记住，这些数字来自默认的 Live 安装环境。如果删除或添加服务和功能，则内存使用量将发生变化。但是，如果要根据内存消耗确定桌面环境，这是一个很好的基准。</p><hr>',19)),l("p",null,[e[1]||(e[1]=o("via: ",-1)),a(t,{href:"https://fedoramagazine.org/fedora-desktops-memory-footprints/"},{default:r(()=>[...e[0]||(e[0]=[o("https://fedoramagazine.org/fedora-desktops-memory-footprints/",-1)])]),_:1})]),l("p",null,[e[6]||(e[6]=o("作者：",-1)),a(t,{href:"https://fedoramagazine.org/author/tdawson/"},{default:r(()=>[...e[2]||(e[2]=[o("Troy Dawson",-1)])]),_:1}),e[7]||(e[7]=o(" 选题：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:r(()=>[...e[3]||(e[3]=[o("lujun9972",-1)])]),_:1}),e[8]||(e[8]=o(" 译者：",-1)),a(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1}),e[9]||(e[9]=o(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[5]||(e[5]=[o("wxy",-1)])]),_:1})]),l("p",null,[e[12]||(e[12]=o("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[10]||(e[10]=[o("LCTT",-1)])]),_:1}),e[13]||(e[13]=o(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:r(()=>[...e[11]||(e[11]=[o("Linux中国",-1)])]),_:1}),e[14]||(e[14]=o(" 荣誉推出",-1))])])}const M=i(m,[["render",u]]);export{F as __pageData,M as default};
